 void shell(String command)throws Exception{try(InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(getUiAutomation().executeShellCommand(command))){in.readAllBytes();}}
 void ok(boolean b,String n){if(!b)throw new AssertionError(n);checks.put(n);}
 void await(BooleanSupplier b,String n)throws Exception{long until=SystemClock.elapsedRealtime()+15000;while(!b.getAsBoolean()&&SystemClock.elapsedRealtime()<until)Thread.sleep(40);ok(b.getAsBoolean(),n);}
 static Object field(Object o,String n){try{java.lang.reflect.Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}catch(Exception e){throw new RuntimeException(e);}}
 static void value(Object o,String n,Object v){try{java.lang.reflect.Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);f.set(o,v);}catch(Exception e){throw new RuntimeException(e);}}
 Button find(View v,String text){if(v instanceof Button&&((Button)v).getText().toString().equals(text))return (Button)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){Button b=find(((ViewGroup)v).getChildAt(i),text);if(b!=null)return b;}return null;}
