 void reader()throws Exception{SourceReaderActivity reader=(SourceReaderActivity)open(SourceReaderActivity.class,new Intent().putExtra("record",left));await(()->reader.content!=null,"source_loaded");ok(reader.entry.id==left,"source_identity");action("Close reader");contrast(reader.content,reader.cream?ReaderUi.NAVY:ReaderUi.CREAM,"reader_body");capture("reader-long-title");click("Reading options");click("Switch reading theme");contrast(reader.content,reader.cream?ReaderUi.NAVY:ReaderUi.CREAM,"reader_alternate_theme");int bar=reader.getWindow().getStatusBarColor();int theme=reader.cream?ReaderUi.NAVY:ReaderUi.CREAM;ok((bar==Color.TRANSPARENT||bar==ReaderUi.NAVY)&&reader.scroll.getBackground() instanceof android.graphics.drawable.ColorDrawable&&((android.graphics.drawable.ColorDrawable)reader.scroll.getBackground()).getColor()==theme,"reader_status_theme");ok(((reader.getWindow().getDecorView().getSystemUiVisibility()&View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR)!=0)==true,"reader_status_icon_contrast");report.put(key+"_reader_status_color",bar);capture("reader-theme");runOnMainSync(()->reader.scroll.scrollTo(0,500));Thread.sleep(200);int position=reader.scroll.getScrollY();ok(position>0,"reader_scrolled");close();final SourceReaderActivity restored=(SourceReaderActivity)open(SourceReaderActivity.class,new Intent().putExtra("record",left));await(()->restored.content!=null,"reader_reopened");await(()->restored.scroll.getScrollY()==position,"reader_position_retained");action("Close reader");click("Close reader");ok(restored.isFinishing(),"reader_return");activity=null;}
 boolean idle(PersonalDocumentsActivity a){return !(boolean)field(a,"busy");}
